import argparse
import concurrent.futures
import datetime
import os
import sys
import xml.etree.ElementTree as ET
from threading import Lock

def parse_xml(config_path):
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
        if root.tag != 'tasks':
            raise ValueError("Root element must be 'tasks'")
        return root.findall('task')
    except (ET.ParseError, FileNotFoundError, OSError) as e:
        print(f"Error reading XML file: {e}", file=sys.stderr)
        sys.exit(1)

def execute_task(task_name, command):
    try:
        result = os.system(command)
        return (task_name, f"exit={result}")
    except Exception as e:
        return (task_name, f"error: {str(e)}")

def process_tasks(tasks, max_parallel):
    log_file = "run.log"
    log_lock = Lock()
    succeeded = 0
    failed = 0

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_parallel) as executor:
        futures = []
        for task in tasks:
            name = task.get('name')
            cmd = task.get('command')
            if not name or not cmd:
                print(f"Invalid task: missing name or command in task", file=sys.stderr)
                continue
            futures.append(executor.submit(execute_task, name, cmd))

        for future in concurrent.futures.as_completed(futures):
            task_name, status = future.result()
            timestamp = datetime.datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
            with log_lock:
                with open(log_file, 'a') as f:
                    f.write(f"{timestamp} {task_name} {status}\n")
            if status.startswith("exit="):
                succeeded += 1
            else:
                failed += 1

    return succeeded, failed

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--config', default='tasks.xml', help='Path to XML configuration file')
    parser.add_argument('--max-parallel', type=int, default=2, help='Maximum number of parallel tasks')
    args = parser.parse_args()

    tasks = parse_xml(args.config)
    succeeded, failed = process_tasks(tasks, args.max_parallel)
    print(f"tasks: {len(tasks)}, succeeded: {succeeded}, failed: {failed}")

if __name__ == "__main__":
    main()
